import argon2 from 'argon2';
import { ConflictError } from '../errors.js';
import type { Repos } from '../repositories/index.js';
import type { User } from '../repositories/user-repository.js';
import type { PublicUser, RegisterBody } from '../schemas/auth.js';

// argon2id with the second recommended option of RFC 9106 (also the
// node-argon2 defaults), written out so a change is a visible decision.
// Salt: 16 random bytes per hash, generated by argon2 and stored in the
// PHC string ($argon2id$v=19$m=65536,t=3,p=4$<salt>$<hash>).
const MEMORY_COST_KIB = 65_536; // 64 MiB per hash
const TIME_COST = 3; // iterations
const PARALLELISM = 4; // lanes

const HASH_OPTIONS = {
  type: argon2.argon2id,
  memoryCost: MEMORY_COST_KIB,
  timeCost: TIME_COST,
  parallelism: PARALLELISM,
} as const;

export async function hashPassword(password: string): Promise<string> {
  return await argon2.hash(password, HASH_OPTIONS);
}

export function toPublicUser(user: User): PublicUser {
  return {
    id: user.id,
    email: user.email,
    role: user.role,
    createdAt: user.createdAt,
  };
}

export async function registerUser(
  repos: Repos,
  input: RegisterBody
): Promise<PublicUser> {
  // Hashed before the insert, so a taken and a free address cost the same.
  const passwordHash = await hashPassword(input.password);
  const user = await repos.users.create({
    email: input.email,
    passwordHash,
    role: 'user',
  });
  if (user === null) {
    // A deliberate trade-off: honest to the user, but it reveals that the
    // address is registered
    throw new ConflictError('An account with this e-mail address exists.');
  }
  return toPublicUser(user);
}
